CREATE TABLE object_nodes(id TEXT NOT NULL,user_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('task','note','project','event','resource')),PRIMARY KEY(id,user_id,kind));
INSERT INTO object_nodes SELECT id,user_id,'task' FROM tasks;
CREATE TRIGGER node_tasks_insert AFTER INSERT ON tasks BEGIN INSERT INTO object_nodes VALUES(NEW.id,NEW.user_id,'task'); END;
CREATE TRIGGER node_tasks_delete AFTER DELETE ON tasks BEGIN DELETE FROM object_nodes WHERE id=OLD.id AND user_id=OLD.user_id AND kind='task'; END;
INSERT INTO object_nodes SELECT id,user_id,'note' FROM notes;
CREATE TRIGGER node_notes_insert AFTER INSERT ON notes BEGIN INSERT INTO object_nodes VALUES(NEW.id,NEW.user_id,'note'); END;
CREATE TRIGGER node_notes_delete AFTER DELETE ON notes BEGIN DELETE FROM object_nodes WHERE id=OLD.id AND user_id=OLD.user_id AND kind='note'; END;
INSERT INTO object_nodes SELECT id,user_id,'project' FROM projects;
CREATE TRIGGER node_projects_insert AFTER INSERT ON projects BEGIN INSERT INTO object_nodes VALUES(NEW.id,NEW.user_id,'project'); END;
CREATE TRIGGER node_projects_delete AFTER DELETE ON projects BEGIN DELETE FROM object_nodes WHERE id=OLD.id AND user_id=OLD.user_id AND kind='project'; END;
INSERT INTO object_nodes SELECT id,user_id,'event' FROM events;
CREATE TRIGGER node_events_insert AFTER INSERT ON events BEGIN INSERT INTO object_nodes VALUES(NEW.id,NEW.user_id,'event'); END;
CREATE TRIGGER node_events_delete AFTER DELETE ON events BEGIN DELETE FROM object_nodes WHERE id=OLD.id AND user_id=OLD.user_id AND kind='event'; END;
INSERT INTO object_nodes SELECT id,user_id,'resource' FROM library_items;
CREATE TRIGGER node_library_items_insert AFTER INSERT ON library_items BEGIN INSERT INTO object_nodes VALUES(NEW.id,NEW.user_id,'resource'); END;
CREATE TRIGGER node_library_items_delete AFTER DELETE ON library_items BEGIN DELETE FROM object_nodes WHERE id=OLD.id AND user_id=OLD.user_id AND kind='resource'; END;
CREATE TABLE object_relations(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,remote_updated_at TEXT,sync_state TEXT NOT NULL DEFAULT 'local' CHECK(sync_state IN ('local','imported','modified')),source_id TEXT NOT NULL,source_kind TEXT NOT NULL,target_id TEXT NOT NULL,target_kind TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('references','belongs_to','depends_on')),UNIQUE(user_id,source_id,source_kind,target_id,target_kind,kind),FOREIGN KEY(source_id,user_id,source_kind) REFERENCES object_nodes(id,user_id,kind) ON DELETE CASCADE,FOREIGN KEY(target_id,user_id,target_kind) REFERENCES object_nodes(id,user_id,kind) ON DELETE CASCADE,CHECK(source_id<>target_id OR source_kind<>target_kind));
CREATE TRIGGER sync_object_relations_insert AFTER INSERT ON object_relations WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,payload,base_revision,base_updated_at) VALUES('object_relations',NEW.id,'put',json_object('id',NEW.id,'user_id',NEW.user_id,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'source_id',NEW.source_id,'source_kind',NEW.source_kind,'target_id',NEW.target_id,'target_kind',NEW.target_kind,'kind',NEW.kind),(SELECT revision FROM native_sync_meta WHERE entity_table='object_relations' AND id=NEW.id),COALESCE((SELECT remote_updated_at FROM native_sync_meta WHERE entity_table='object_relations' AND id=NEW.id),NEW.remote_updated_at)); END;
CREATE TRIGGER sync_object_relations_update AFTER UPDATE ON object_relations WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,payload,base_revision,base_updated_at) VALUES('object_relations',NEW.id,'put',json_object('id',NEW.id,'user_id',NEW.user_id,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'source_id',NEW.source_id,'source_kind',NEW.source_kind,'target_id',NEW.target_id,'target_kind',NEW.target_kind,'kind',NEW.kind),(SELECT revision FROM native_sync_meta WHERE entity_table='object_relations' AND id=NEW.id),COALESCE((SELECT remote_updated_at FROM native_sync_meta WHERE entity_table='object_relations' AND id=NEW.id),NEW.remote_updated_at)); END;
CREATE TRIGGER sync_object_relations_delete AFTER DELETE ON object_relations WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,base_revision,base_updated_at) VALUES('object_relations',OLD.id,'delete',(SELECT revision FROM native_sync_meta WHERE entity_table='object_relations' AND id=OLD.id),OLD.remote_updated_at); END;
CREATE TABLE user_quotes(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,remote_updated_at TEXT,sync_state TEXT NOT NULL DEFAULT 'local' CHECK(sync_state IN ('local','imported','modified')),content TEXT NOT NULL CHECK(length(trim(content)) BETWEEN 1 AND 2000),author TEXT NOT NULL CHECK(length(author)<=200),favorite INTEGER NOT NULL CHECK(favorite IN (0,1)));
CREATE TRIGGER sync_user_quotes_insert AFTER INSERT ON user_quotes WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,payload,base_revision,base_updated_at) VALUES('user_quotes',NEW.id,'put',json_object('id',NEW.id,'user_id',NEW.user_id,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'content',NEW.content,'author',NEW.author,'favorite',NEW.favorite),(SELECT revision FROM native_sync_meta WHERE entity_table='user_quotes' AND id=NEW.id),COALESCE((SELECT remote_updated_at FROM native_sync_meta WHERE entity_table='user_quotes' AND id=NEW.id),NEW.remote_updated_at)); END;
CREATE TRIGGER sync_user_quotes_update AFTER UPDATE ON user_quotes WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,payload,base_revision,base_updated_at) VALUES('user_quotes',NEW.id,'put',json_object('id',NEW.id,'user_id',NEW.user_id,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'content',NEW.content,'author',NEW.author,'favorite',NEW.favorite),(SELECT revision FROM native_sync_meta WHERE entity_table='user_quotes' AND id=NEW.id),COALESCE((SELECT remote_updated_at FROM native_sync_meta WHERE entity_table='user_quotes' AND id=NEW.id),NEW.remote_updated_at)); END;
CREATE TRIGGER sync_user_quotes_delete AFTER DELETE ON user_quotes WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,base_revision,base_updated_at) VALUES('user_quotes',OLD.id,'delete',(SELECT revision FROM native_sync_meta WHERE entity_table='user_quotes' AND id=OLD.id),OLD.remote_updated_at); END;
CREATE INDEX relation_source ON object_relations(source_id,user_id,source_kind);
CREATE INDEX relation_target ON object_relations(target_id,user_id,target_kind);
CREATE TRIGGER relation_cycle_insert BEFORE INSERT ON object_relations WHEN NEW.kind='depends_on' BEGIN SELECT RAISE(ABORT,'Dependency cycle') WHERE EXISTS(WITH RECURSIVE reachable(id,kind) AS (SELECT NEW.target_id,NEW.target_kind UNION SELECT r.target_id,r.target_kind FROM object_relations r JOIN reachable p ON r.source_id=p.id AND r.source_kind=p.kind WHERE r.kind='depends_on' AND r.user_id=NEW.user_id AND r.id<>NEW.id) SELECT 1 FROM reachable WHERE id=NEW.source_id AND kind=NEW.source_kind); END;
CREATE TRIGGER relation_cycle_update BEFORE UPDATE ON object_relations WHEN NEW.kind='depends_on' BEGIN SELECT RAISE(ABORT,'Dependency cycle') WHERE EXISTS(WITH RECURSIVE reachable(id,kind) AS (SELECT NEW.target_id,NEW.target_kind UNION SELECT r.target_id,r.target_kind FROM object_relations r JOIN reachable p ON r.source_id=p.id AND r.source_kind=p.kind WHERE r.kind='depends_on' AND r.user_id=NEW.user_id AND r.id<>NEW.id) SELECT 1 FROM reachable WHERE id=NEW.source_id AND kind=NEW.source_kind); END;
